// The code is MPL-2.0. The message wording, copied from src/errors/errors.toml, is CC-BY-SA-4.0.
// GENERATED by scripts/gen-errors-rs.sh from src/errors/errors.toml. Do not edit: change the TOML and run the script.
// Included by src/msg.rs, so the slot classes keep their fields private to that module.

/// One `[[error]]`. `explain` is the text of `idris2x explain ID` up to its runbook line.
pub(crate) struct ErrorDef { id: &'static str, title: &'static str, exit: u8, explain: &'static str }
/// One `[[case]]`: its error (an index into `ERRORS`), its templates, and its facts as (label, key).
pub(crate) struct CaseDef {
    error: usize, case: &'static str, summary: &'static str, story: &'static str, facts: &'static [(&'static str, &'static str)], state: &'static str,
    why: &'static str, fix_lead: &'static str, fix_cmd: &'static str, fix_note: &'static str, auto: &'static str,
}
/// One `[[advice]]`: a note that is not an error, its facts as (label, key), and the variable that silences it.
pub(crate) struct AdviceDef { text: &'static str, facts: &'static [(&'static str, &'static str)], silence: &'static str }

/// The text of `idris2x explain` with no id: one line per error.
pub(crate) static EXPLAIN_ALL: &str = "E-USAGE                 exit  2  the command line was not understood\nE-PIN-NOT-FOUND         exit 10  nothing is pinned for this version and target\nE-HASH-MISMATCH         exit 11  capsule bytes do not match the lock\nE-SIG-INVALID           exit 12  channel manifest signature or key does not verify\nE-PLATFORM-UNSUPPORTED  exit 13  no capsule exists for this kind of machine\nE-NETWORK               exit 14  the download could not be completed\nE-LOCK-TIMEOUT          exit 15  another idris2x is installing the same capsule\nE-GLIBC-FLOOR           exit 16  this system's C library is older than the capsule needs\nE-PROBE-CODEGEN         exit 17  the installed toolchain failed a self-check on this machine\nE-CHANNEL-SCHEMA        exit 18  a file was written for a newer idris2x\nE-PIN-DRIFT             exit 19  idris2x.toml and idris2x.lock disagree\nE-OFFLINE               exit 20  needed data is not cached and offline mode is on\nE-CAPSULE-INVALID       exit 21  the capsule archive is malformed or unsafe\nE-CHANNEL-ROLLBACK      exit 22  the channel offered an older manifest than one already seen\nE-CHANNEL-EXPIRED       exit 23  the channel manifest is past its expiry time\nE-STORE-IO              exit 24  the store could not be written\nE-OUTPUT                exit 25  the output could not be written\nE-INTERNAL              exit 70  idris2x has a bug\n";

pub(crate) static ERRORS: [ErrorDef; 18] = [
    ErrorDef { id: "E-USAGE", title: "the command line was not understood", exit: 2, explain: "E-USAGE (exit 2): the command line was not understood\n\nMeaning: bad command line\nUsual fix: idris2x --help\n\nIt takes 7 shape(s). Words in {braces} are filled in when it happens.\n\n  unknown-command: no such command: {word}\n    why: The first word after idris2x must be one of the commands listed above.\n    now: Nothing was run.\n    fix: idris2x help\n\n  unknown-flag: {command} does not take {word}\n    why: Each command accepts only the flags shown in its usage line.\n    now: Nothing was run.\n    note: Run the command again in the form shown after usage.\n\n  missing-argument: {command} needs {what}\n    why: The command cannot choose this value for you.\n    now: Nothing was run.\n    note: Run the command again in the form shown after usage.\n\n  no-such-file: no such file: {path}\n    why: A relative path is read from the current directory.\n    now: Nothing was installed or changed.\n    note: Check the spelling, or give the full path.\n\n  no-such-id: no such error id: {word}\n    why: Error ids are written in capitals and start with E-, exactly as a message prints them.\n    now: Nothing was run.\n    fix: idris2x explain\n\n  prototype-setting: {variable} is not set\n    why: The bash prototype reads its channel address and trusted key from the environment. The real launcher will have both built in.\n    now: Nothing was run.\n    note: Set {variable} and run the command again. See scripts/proto/chaos.sh for a working example.\n\n  bad-setting: {variable} is not {what}\n    why: idris2x refuses a setting it cannot read. It does not fall back to a default, so a typo never changes what runs.\n    now: Nothing was run.\n    note: Set {variable} to {what}, or unset it to use the default.\n\n" },
    ErrorDef { id: "E-PIN-NOT-FOUND", title: "nothing is pinned for this version and target", exit: 10, explain: "E-PIN-NOT-FOUND (exit 10): nothing is pinned for this version and target\n\nMeaning: no lock, or lock/channel has no capsule for this version+target\nUsual fix: idris2x pin <supported-version>\n\nIt takes 8 shape(s). Words in {braces} are filled in when it happens.\n\n  no-lock: no {lock} in {dir}\n    why: idris2x never guesses a version. Every run is tied to a lock file, so the same command gives the same compiler on every machine.\n    now: Nothing was downloaded or changed.\n    fix: idris2x pin <version>\n    note: If the project already has a lock file, change to the directory that holds it: the lock is read from the current directory only.\n\n  no-target: {lock} pins no capsule for {target}\n    why: The lock records one capsule per platform. It was written when the channel had none for this platform.\n    now: Nothing was downloaded or changed.\n    fix: idris2x pin {version}\n    note: If {target} is still missing afterwards, no capsule is published for it yet: see the supported platforms page.\n\n  no-version: the channel has no idris2 {version}\n    why: Only versions with a published, signed capsule can be pinned.\n    now: {lock} was not changed.\n    fix: idris2x pin <version>\n\n  not-installed: the pinned capsule is not installed\n    why: verify checks a capsule that is already in the store. It does not download one.\n    now: Nothing was changed.\n    fix: idris2x install --locked\n\n  no-idris2: the pinned capsule holds Chez Scheme only, not Idris 2\n    why: Some capsules carry only Chez Scheme. They serve idris2x run, not idris2x exec.\n    now: Nothing was changed.\n    note: Pin a version of Idris 2 with idris2x pin, or use idris2x run to start Chez Scheme.\n\n  no-urls: {lock} lists no download address for this machine's capsule\n    why: The lock file was edited by hand, or written by a faulty tool. A lock written by idris2x pin always lists at least one address.\n    now: Nothing was downloaded or changed.\n    fix: idris2x pin {version}\n\n  malformed-lock: {lock} has a malformed {field} for this machine\n    why: A digest is exactly 64 lowercase hexadecimal characters and a version is numbers separated by dots. Anything else means the lock was edited by hand or damaged, and it is refused before it can reach a download, a store path or a printed command.\n    now: Nothing was downloaded or changed.\n    fix: idris2x pin <version>\n    note: If the lock is under version control, compare it with the last committed version first.\n\n  unreadable-lock: cannot read {lock} as a lock file\n    why: A lock is JSON that idris2x pin writes. A file that cannot be opened, or that is not that JSON, is refused, not guessed at.\n    now: Nothing was downloaded or changed.\n    fix: idris2x pin <version>\n    note: If the lock is under version control, compare it with the last committed version first.\n\n" },
    ErrorDef { id: "E-HASH-MISMATCH", title: "capsule bytes do not match the lock", exit: 11, explain: "E-HASH-MISMATCH (exit 11): capsule bytes do not match the lock\n\nMeaning: downloaded bytes or unpacked tree do not match the pinned digest\nUsual fix: idris2x install --locked\n\nIt takes 3 shape(s). Words in {braces} are filled in when it happens.\n\n  download: downloaded capsule does not match {lock}\n    why: A mirror served a damaged, truncated or stale file. It can also mean tampering, which is what this check exists to catch.\n    now: Nothing was installed. The bad download was deleted and the store is unchanged.\n    fix: idris2x install --locked\n    note: If it fails again with the same got digest, the mirror is serving a bad file: report it with the runbook below.\n\n  bundle: bundle {source} does not match {lock}\n    why: The bundle was fetched for a different lock file, or it was damaged in transit.\n    now: Nothing was installed. Your bundle file was left untouched.\n    fix: idris2x fetch -o capsule.tar.gz\n    note: Run that on a connected machine with this exact {lock}, then copy the new bundle here.\n\n  store-modified: an installed capsule was modified after installation\n    why: Files in the store changed after installation: by hand, by another tool, or through disk corruption. The store is meant to be read-only.\n    now: The capsule was left in place so that you can inspect it.\n    fix: rm -rf {dir} && idris2x install --locked\n    note: Programs compiled with this capsule keep working once it is reinstalled, because the store path stays the same.\n\n" },
    ErrorDef { id: "E-SIG-INVALID", title: "channel manifest signature or key does not verify", exit: 12, explain: "E-SIG-INVALID (exit 12): channel manifest signature or key does not verify\n\nMeaning: channel manifest signature or key id does not verify\nUsual fix: do not override; investigate the mirror (runbook)\n\nIt takes 3 shape(s). Words in {braces} are filled in when it happens.\n\n  bad-signature: channel manifest signature does not verify\n    why: The manifest was altered after it was signed, or a mirror served a manifest and a signature from two different publishes.\n    now: The manifest was discarded. Your lock file and store are unchanged, and everything already pinned still runs.\n    fix: idris2x pin {version}\n    note: If it fails again, stop: there is no flag that skips this check. Follow the runbook below to report the mirror.\n\n  wrong-key: channel manifest was signed by an untrusted key\n    why: This URL is not the channel this idris2x trusts, or the channel changed its key after this idris2x was released, or someone is impersonating the channel.\n    now: The manifest was discarded. Your lock file and store are unchanged, and everything already pinned still runs.\n    note: Check that the manifest URL is the channel you meant. If it is, update idris2x, because key changes ship in launcher releases. Never swap the trusted key by hand.\n\n  malformed: cannot read signature material: {what}\n    why: The file is not a signify-format Ed25519 key or signature. A proxy or captive portal that returns a web page in place of the file is the usual cause.\n    now: The manifest was discarded. Your lock file and store are unchanged, and everything already pinned still runs.\n    note: Open the file named above. If it contains HTML, fix the proxy or network first, then run the same command again.\n\n" },
    ErrorDef { id: "E-PLATFORM-UNSUPPORTED", title: "no capsule exists for this kind of machine", exit: 13, explain: "E-PLATFORM-UNSUPPORTED (exit 13): no capsule exists for this kind of machine\n\nMeaning: no capsule exists for this OS/arch\nUsual fix: see supported targets; consider --from-source (Tier 3)\n\nIt takes 2 shape(s). Words in {braces} are filled in when it happens.\n\n  unknown-arch: no capsules are built for the {arch} processor type\n    why: Each capsule holds programs compiled for one processor type and operating system, and none has been built for this pair.\n    now: Nothing was downloaded or changed.\n    note: See the supported platforms page for the list and for how to ask for a new target. Building Idris 2 from source remains possible without idris2x.\n\n  unknown-os: no capsules are built for the {os} operating system\n    why: Each capsule holds programs compiled for one processor type and operating system, and none has been built for this pair.\n    now: Nothing was downloaded or changed.\n    note: See the supported platforms page for the list and for how to ask for a new target. Building Idris 2 from source remains possible without idris2x.\n\n" },
    ErrorDef { id: "E-NETWORK", title: "the download could not be completed", exit: 14, explain: "E-NETWORK (exit 14): the download could not be completed\n\nMeaning: all mirrors failed\nUsual fix: retry; check proxy; IDRIS2X_OFFLINE=1 with a prefetched bundle\n\nIt takes 2 shape(s). Words in {braces} are filled in when it happens.\n\n  all-mirrors-failed: every mirror failed for the pinned capsule\n    why: Each address in the lock was tried in turn and each one failed for the reason shown after it.\n    now: Nothing was installed. The store is unchanged.\n    fix: idris2x install --locked\n    note: If you are behind a proxy, check that HTTPS_PROXY is set. If every mirror answers 404, the capsule was withdrawn: see the runbook below.\n\n  manifest-unreachable: cannot fetch the channel manifest\n    why: pin needs a fresh copy of the signed manifest, and the address above did not provide one.\n    now: The lock file was not changed. Everything already pinned still runs.\n    fix: idris2x pin {version}\n    note: Running an already pinned toolchain does not need the network once its capsule is installed.\n\n" },
    ErrorDef { id: "E-LOCK-TIMEOUT", title: "another idris2x is installing the same capsule", exit: 15, explain: "E-LOCK-TIMEOUT (exit 15): another idris2x is installing the same capsule\n\nMeaning: another install of the same capsule held the lock too long\nUsual fix: wait for the other install, or raise IDRIS2X_LOCK_TIMEOUT; never delete a lock that is held\n\nIt takes 1 shape(s). Words in {braces} are filled in when it happens.\n\n  held: waited {seconds}s for another install of the same capsule\n    why: Installs of one capsule take turns, so two processes never write the same store entry. A slow download in the other process is the usual cause.\n    now: This run installed nothing. The other install is not affected.\n    fix: IDRIS2X_LOCK_TIMEOUT=1800 idris2x install --locked\n    note: Do not delete the lock file while its holder is running: two installs would then write at once. The lock is released by itself when the holder exits.\n\n" },
    ErrorDef { id: "E-GLIBC-FLOOR", title: "this system's C library is older than the capsule needs", exit: 16, explain: "E-GLIBC-FLOOR (exit 16): this system's C library is older than the capsule needs\n\nMeaning: host glibc older than the capsule's min_glibc\nUsual fix: upgrade the host or use a musl/static capsule when available\n\nIt takes 2 shape(s). Words in {braces} are filled in when it happens.\n\n  too-old: this system has glibc {host}, older than the pinned capsule needs\n    why: The capsule's programs were built against a newer glibc. On an older glibc they would fail to start, with a less clear message than this one.\n    now: Nothing was downloaded or changed.\n    note: Run this project in a newer distribution or container image, one with at least the glibc shown above. This check cannot be skipped.\n\n  unknown: cannot tell which glibc this system has\n    why: idris2x asks getconf GNU_LIBC_VERSION, with only PATH passed on from the environment. Either getconf is not on PATH, or this system's C library is not glibc: musl, as on Alpine, is not supported. A capsule on a C library it was not built for fails to start, with a less clear message than this one.\n    now: Nothing was downloaded or changed.\n    note: Put getconf on PATH (on Debian and Ubuntu it is in the libc-bin package), or run this project in a glibc-based distribution or container image. This check cannot be skipped.\n\n" },
    ErrorDef { id: "E-PROBE-CODEGEN", title: "the installed toolchain failed a self-check on this machine", exit: 17, explain: "E-PROBE-CODEGEN (exit 17): the installed toolchain failed a self-check on this machine\n\nMeaning: capsule unpacked and verified but a canary failed on this host\nUsual fix: runbook triage; idris2x doctor --json\n\nIt takes 5 shape(s). Words in {braces} are filled in when it happens.\n\n  chez-failed: Chez Scheme from the capsule does not run here\n    why: The capsule's files are intact, since the checksums passed, so something about this machine stops the program running: a missing system library, a security policy, or an unsupported processor.\n    now: The capsule was not installed. The store is unchanged.\n    fix: idris2x doctor\n    note: The line after chez-said is Chez Scheme's own message, not ours. Send it with the doctor output using the runbook below.\n\n  idris2-failed: Idris 2 from the capsule does not start here\n    why: Chez Scheme runs, so the fault is in starting the compiler itself: usually its support library could not be loaded.\n    now: The capsule was not installed. The store is unchanged.\n    fix: idris2x doctor\n    note: The line after idris2-said is Idris 2's own message, not ours. Report this to idris2x, not to the Idris 2 project: the fault is in how the capsule was built or run.\n\n  version-mismatch: the compiler in the capsule reports a different version than the capsule says it holds\n    why: The capsule was labelled wrongly when it was built. This is a fault in the capsule, not in your machine.\n    now: The capsule was not installed. The store is unchanged.\n    note: Report the capsule using the runbook below. Until it is replaced, pin a different version.\n\n  path-has-spaces: compiled programs cannot start because the store path contains a space\n    why: A compiled program begins with a line naming Chez Scheme by its full path, and the operating system splits that line at spaces.\n    now: The capsule is installed and the compiler itself works. Only programs it compiles with the Chez backend are affected.\n    fix: export IDRIS2X_CACHE=\"$HOME/.cache/idris2x\"\n    note: Any directory whose full path has no spaces will do. Programs built with --cg refc are not affected.\n\n  codegen-failed: a test program did not compile and run: {probe}\n    why: The compiler starts, and building or running a program with it fails on this machine.\n    now: The capsule is installed. Nothing else was changed.\n    fix: idris2x doctor\n    note: Send the doctor output using the runbook below.\n\n" },
    ErrorDef { id: "E-CHANNEL-SCHEMA", title: "a file was written for a newer idris2x", exit: 18, explain: "E-CHANNEL-SCHEMA (exit 18): a file was written for a newer idris2x\n\nMeaning: channel or lock schema newer than this launcher\nUsual fix: update idris2x\n\nIt takes 2 shape(s). Words in {braces} are filled in when it happens.\n\n  lock-newer: {file} uses a newer lock format; this idris2x reads up to {supports}\n    why: Someone pinned this project with a newer idris2x. An older one refuses to guess at fields it does not know.\n    now: Nothing was downloaded or changed. The lock file is intact.\n    note: Update idris2x to the version your colleagues use, then run the same command again.\n\n  channel-newer: the channel uses a newer manifest format; this idris2x reads up to {supports}\n    why: The channel moved to a new format after this idris2x was released.\n    now: The lock file was not changed. Everything already pinned still runs.\n    note: Update idris2x, then pin again. Until then, existing pins keep working.\n\n" },
    ErrorDef { id: "E-PIN-DRIFT", title: "idris2x.toml and idris2x.lock disagree", exit: 19, explain: "E-PIN-DRIFT (exit 19): idris2x.toml and idris2x.lock disagree\n\nMeaning: idris2x.toml and idris2x.lock disagree\nUsual fix: idris2x pin <version>\n\nIt takes 1 shape(s). Words in {braces} are filled in when it happens.\n\n  toml-vs-lock: idris2x.toml asks for a different idris2 version than idris2x.lock pins\n    why: One of the two files was edited without the other. With --locked the lock is never rewritten to match.\n    now: Nothing was downloaded or changed.\n    fix: idris2x pin {toml}\n    note: If the lock is the one that is right, change the version in idris2x.toml to the one idris2x.lock pins instead.\n\n" },
    ErrorDef { id: "E-OFFLINE", title: "needed data is not cached and offline mode is on", exit: 20, explain: "E-OFFLINE (exit 20): needed data is not cached and offline mode is on\n\nMeaning: cache miss while IDRIS2X_OFFLINE=1\nUsual fix: idris2x fetch -o bundle on a connected host, then idris2x install --from bundle\n\nIt takes 2 shape(s). Words in {braces} are filled in when it happens.\n\n  capsule-missing: a pinned capsule is not in the store and {mode} is set\n    why: Offline mode never touches the network, so the capsule has to arrive another way.\n    now: Nothing was downloaded, as you asked. The store is unchanged.\n    fix: idris2x fetch -o capsule.tar.gz\n    note: Run that on a connected machine with the same {lock}, copy capsule.tar.gz here, then run: idris2x install --from capsule.tar.gz\n\n  no-manifest: no cached channel manifest and {mode} is set\n    why: pin reads the signed channel manifest. Offline, it can only use a copy cached by an earlier online pin.\n    now: Nothing was changed.\n    fix: IDRIS2X_OFFLINE=0 idris2x pin {version}\n    note: Running an already pinned toolchain never needs the manifest: install --locked and exec --locked work offline from the store.\n\n" },
    ErrorDef { id: "E-CAPSULE-INVALID", title: "the capsule archive is malformed or unsafe", exit: 21, explain: "E-CAPSULE-INVALID (exit 21): the capsule archive is malformed or unsafe\n\nMeaning: capsule archive is malformed or contains unsafe paths/links\nUsual fix: report the digest; never unpack by hand\n\nIt takes 4 shape(s). Words in {braces} are filled in when it happens.\n\n  unsafe-path: the capsule archive has a member that would be written outside the store\n    why: The archive has an absolute path, a .. component or a link that leaves its own directory. A correctly built capsule never does, so the archive is faulty or hostile.\n    now: Nothing was unpacked or installed. The archive was deleted.\n    note: Do not unpack it by hand. Report the digest above to idris2x using the runbook below.\n\n  no-metadata: the capsule archive has no capsule.json\n    why: Every capsule describes itself in capsule.json. This archive matched its digest and is not a capsule, which is a fault in how it was built.\n    now: Nothing was installed. The unpacked files were deleted.\n    note: Report the digest above to idris2x using the runbook below.\n\n  tree-mismatch: the capsule's files do not match its own checksum list\n    why: The archive as a whole matched the lock, so the fault was built into the capsule, or the disk damaged the files while unpacking.\n    now: Nothing was installed. The unpacked files were deleted.\n    fix: idris2x install --locked\n    note: If it fails the same way, report the digest above to idris2x using the runbook below.\n\n  bad-metadata: the capsule's capsule.json does not describe it\n    why: capsule.json must be a JSON object that names the capsule, gives its Chez Scheme version and, if the capsule has Idris 2, its version too. This archive matched its digest, so the fault was built into the capsule.\n    now: Nothing was installed. The unpacked files were deleted.\n    note: Report the digest above to idris2x using the runbook below.\n\n" },
    ErrorDef { id: "E-CHANNEL-ROLLBACK", title: "the channel offered an older manifest than one already seen", exit: 22, explain: "E-CHANNEL-ROLLBACK (exit 22): the channel offered an older manifest than one already seen\n\nMeaning: channel_version went backwards relative to the lock (rollback/freeze attack or stale mirror)\nUsual fix: investigate; do not override\n\nIt takes 1 shape(s). Words in {braces} are filled in when it happens.\n\n  version-went-back: the channel offered an older manifest version than this project has already seen\n    why: Manifest versions only go up. An older one usually means a mirror that has not caught up. It can also be an attempt to hide a newer release.\n    now: The lock file was not changed. Everything already pinned still runs.\n    fix: idris2x pin {version}\n    note: If it is still older tomorrow, report it using the runbook below. There is no flag that accepts an older manifest.\n\n" },
    ErrorDef { id: "E-CHANNEL-EXPIRED", title: "the channel manifest is past its expiry time", exit: 23, explain: "E-CHANNEL-EXPIRED (exit 23): the channel manifest is past its expiry time\n\nMeaning: channel manifest past its expires timestamp (freeze protection)\nUsual fix: fetch a fresh manifest; IDRIS2X_ALLOW_EXPIRED=1 only when you know why\n\nIt takes 1 shape(s). Words in {braces} are filled in when it happens.\n\n  expired: the channel manifest has expired\n    why: Manifests are re-signed regularly, so a stale one means a mirror is serving an old copy, the channel is no longer maintained, or this machine's clock is wrong.\n    now: The lock file was not changed. Everything already pinned still runs.\n    fix: idris2x pin {version}\n    note: To pin from the expired manifest anyway, set IDRIS2X_ALLOW_EXPIRED=1. That gives up protection against being shown an outdated list of releases, so use it only when you know why the manifest is old.\n\n" },
    ErrorDef { id: "E-STORE-IO", title: "the store could not be written", exit: 24, explain: "E-STORE-IO (exit 24): the store could not be written\n\nMeaning: store not writable, disk full, or atomic rename failed\nUsual fix: free space / fix permissions; idris2x gc\n\nIt takes 4 shape(s). Words in {braces} are filled in when it happens.\n\n  cannot-create: cannot create {path}\n    why: The directory's parent is missing, read-only, or owned by another user.\n    now: Nothing was installed.\n    fix: export IDRIS2X_CACHE=\"$HOME/.cache/idris2x\"\n    note: The store path must not contain spaces if you compile programs with the Chez backend.\n\n  write-failed: writing to the store failed: {detail}\n    why: The disk is full, a quota or file-size limit was reached, or the store became read-only.\n    now: Nothing was installed. Partly written files were removed, and existing capsules are untouched.\n    fix: idris2x gc\n    note: Then run the same command again.\n\n  rename-failed: cannot move the unpacked capsule into place\n    why: The final step is a single rename, so that a capsule is either complete or absent. The rename fails when the store and its staging area are on different filesystems, or the store is read-only.\n    now: Nothing was installed. The unpacked files were removed.\n    note: Check that the store directory is on one writable filesystem, then run the same command again.\n\n  no-cache-dir: cannot tell where the store should be\n    why: idris2x keeps capsules in IDRIS2X_CACHE, else in XDG_CACHE_HOME/idris2x, else in HOME/.cache/idris2x. It does not fall back to the current directory, which would put a separate store in each project.\n    now: Nothing was downloaded or changed.\n    fix: export IDRIS2X_CACHE=<directory>\n    note: The store path must not contain spaces if you compile programs with the Chez backend.\n\n" },
    ErrorDef { id: "E-OUTPUT", title: "the output could not be written", exit: 25, explain: "E-OUTPUT (exit 25): the output could not be written\n\nMeaning: standard output is full, or the program reading it stopped\nUsual fix: send the output somewhere that can take all of it\n\nIt takes 1 shape(s). Words in {braces} are filled in when it happens.\n\n  write-failed: cannot write the output: {detail}\n    why: The disk or file that the output goes to is full, or the program reading it stopped before the end, as head does.\n    now: The output is incomplete. Anything the command did before it tried to write is kept.\n    note: Send the output to a file on a disk with free space, or to a program that reads all of it, then run the same command again.\n\n" },
    ErrorDef { id: "E-INTERNAL", title: "idris2x has a bug", exit: 70, explain: "E-INTERNAL (exit 70): idris2x has a bug\n\nMeaning: launcher bug\nUsual fix: file an issue with idris2x doctor --json\n\nIt takes 2 shape(s). Words in {braces} are filled in when it happens.\n\n  bug: internal error: {detail}\n    why: This is a fault in idris2x, not something you did.\n    now: Unknown. Run idris2x verify to check the installed capsule.\n    fix: idris2x doctor\n    note: Attach the doctor output and the command you ran to a new issue at https://github.com/metadatastician/idris2x/issues\n\n  missing-tool: the prototype needs {tool} and cannot find it\n    why: The prototype is a shell script that calls ordinary system tools. The real launcher will not need them.\n    now: Nothing was run.\n    note: Install {tool} with your system's package manager, then run the same command again.\n\n" },
];

pub(crate) static CASES: [CaseDef; 51] = [
    CaseDef { error: 1, case: "no-lock", summary: "no {lock} in {dir}", story: "There is no {lock} in this directory, so I do not know which Idris 2 to run.", facts: &[("directory", "dir"), ("looked-for", "lock")],
        state: "Nothing was downloaded or changed.", why: "idris2x never guesses a version. Every run is tied to a lock file, so the same command gives the same compiler on every machine.", fix_lead: "If this is the project root, pin a version here:", fix_cmd: "idris2x pin <version>",
        fix_note: "If the project already has a lock file, change to the directory that holds it: the lock is read from the current directory only.", auto: "placeholder" },
    CaseDef { error: 1, case: "no-target", summary: "{lock} pins no capsule for {target}", story: "{lock} does not pin a capsule for this machine.", facts: &[("this-machine", "target"), ("lock-covers", "covered")],
        state: "Nothing was downloaded or changed.", why: "The lock records one capsule per platform. It was written when the channel had none for this platform.", fix_lead: "Pin again to pick up every platform the channel offers now:", fix_cmd: "idris2x pin {version}",
        fix_note: "If {target} is still missing afterwards, no capsule is published for it yet: see the supported platforms page.", auto: "safe" },
    CaseDef { error: 1, case: "no-version", summary: "the channel has no idris2 {version}", story: "The channel does not offer Idris 2 {version}.", facts: &[("asked-for", "version"), ("available", "available")],
        state: "{lock} was not changed.", why: "Only versions with a published, signed capsule can be pinned.", fix_lead: "Pin one of the available versions:", fix_cmd: "idris2x pin <version>",
        fix_note: "", auto: "placeholder" },
    CaseDef { error: 1, case: "not-installed", summary: "the pinned capsule is not installed", story: "The pinned capsule is not installed yet, so there is nothing to check.", facts: &[("capsule", "digest")],
        state: "Nothing was changed.", why: "verify checks a capsule that is already in the store. It does not download one.", fix_lead: "Install it first:", fix_cmd: "idris2x install --locked",
        fix_note: "", auto: "safe" },
    CaseDef { error: 1, case: "no-idris2", summary: "the pinned capsule holds Chez Scheme only, not Idris 2", story: "The pinned capsule holds Chez Scheme only, so there is no Idris 2 to run.", facts: &[("capsule", "name")],
        state: "Nothing was changed.", why: "Some capsules carry only Chez Scheme. They serve idris2x run, not idris2x exec.", fix_lead: "", fix_cmd: "",
        fix_note: "Pin a version of Idris 2 with idris2x pin, or use idris2x run to start Chez Scheme.", auto: "none" },
    CaseDef { error: 1, case: "no-urls", summary: "{lock} lists no download address for this machine's capsule", story: "{lock} names this machine's capsule and gives no address to download it from.", facts: &[("capsule", "digest")],
        state: "Nothing was downloaded or changed.", why: "The lock file was edited by hand, or written by a faulty tool. A lock written by idris2x pin always lists at least one address.", fix_lead: "Write the lock again from the channel:", fix_cmd: "idris2x pin {version}",
        fix_note: "", auto: "safe" },
    CaseDef { error: 1, case: "malformed-lock", summary: "{lock} has a malformed {field} for this machine", story: "{lock} records a {field} for this machine that is not well formed.", facts: &[("this-machine", "target"), ("field", "field")],
        state: "Nothing was downloaded or changed.", why: "A digest is exactly 64 lowercase hexadecimal characters and a version is numbers separated by dots. Anything else means the lock was edited by hand or damaged, and it is refused before it can reach a download, a store path or a printed command.", fix_lead: "Write the lock again from the channel:", fix_cmd: "idris2x pin <version>",
        fix_note: "If the lock is under version control, compare it with the last committed version first.", auto: "placeholder" },
    CaseDef { error: 1, case: "unreadable-lock", summary: "cannot read {lock} as a lock file", story: "{lock} is here, and I could not read it as a lock file.", facts: &[("problem", "problem")],
        state: "Nothing was downloaded or changed.", why: "A lock is JSON that idris2x pin writes. A file that cannot be opened, or that is not that JSON, is refused, not guessed at.", fix_lead: "Write the lock again from the channel:", fix_cmd: "idris2x pin <version>",
        fix_note: "If the lock is under version control, compare it with the last committed version first.", auto: "placeholder" },
    CaseDef { error: 2, case: "download", summary: "downloaded capsule does not match {lock}", story: "The capsule I downloaded is not the one {lock} pins.", facts: &[("expected", "want"), ("got", "got"), ("size", "bytes"), ("from", "source")],
        state: "Nothing was installed. The bad download was deleted and the store is unchanged.", why: "A mirror served a damaged, truncated or stale file. It can also mean tampering, which is what this check exists to catch.", fix_lead: "Try the download again:", fix_cmd: "idris2x install --locked",
        fix_note: "If it fails again with the same got digest, the mirror is serving a bad file: report it with the runbook below.", auto: "safe" },
    CaseDef { error: 2, case: "bundle", summary: "bundle {source} does not match {lock}", story: "The bundle you gave me is not the capsule {lock} pins.", facts: &[("expected", "want"), ("got", "got"), ("size", "bytes"), ("bundle", "source")],
        state: "Nothing was installed. Your bundle file was left untouched.", why: "The bundle was fetched for a different lock file, or it was damaged in transit.", fix_lead: "", fix_cmd: "idris2x fetch -o capsule.tar.gz",
        fix_note: "Run that on a connected machine with this exact {lock}, then copy the new bundle here.", auto: "none" },
    CaseDef { error: 2, case: "store-modified", summary: "an installed capsule was modified after installation", story: "An installed capsule no longer matches its own checksums.", facts: &[("capsule", "digest"), ("store-entry", "dir")],
        state: "The capsule was left in place so that you can inspect it.", why: "Files in the store changed after installation: by hand, by another tool, or through disk corruption. The store is meant to be read-only.", fix_lead: "Remove this capsule and install it again:", fix_cmd: "rm -rf {dir} && idris2x install --locked",
        fix_note: "Programs compiled with this capsule keep working once it is reinstalled, because the store path stays the same.", auto: "none" },
    CaseDef { error: 3, case: "bad-signature", summary: "channel manifest signature does not verify", story: "The channel manifest's signature does not match its contents.", facts: &[("manifest", "url"), ("trusted-key", "key")],
        state: "The manifest was discarded. Your lock file and store are unchanged, and everything already pinned still runs.", why: "The manifest was altered after it was signed, or a mirror served a manifest and a signature from two different publishes.", fix_lead: "Wait a minute, then try once more in case a mirror was mid-update:", fix_cmd: "idris2x pin {version}",
        fix_note: "If it fails again, stop: there is no flag that skips this check. Follow the runbook below to report the mirror.", auto: "none" },
    CaseDef { error: 3, case: "wrong-key", summary: "channel manifest was signed by an untrusted key", story: "The channel manifest was signed by a key I do not trust.", facts: &[("manifest", "url"), ("signed-by", "signer"), ("trusted-key", "key")],
        state: "The manifest was discarded. Your lock file and store are unchanged, and everything already pinned still runs.", why: "This URL is not the channel this idris2x trusts, or the channel changed its key after this idris2x was released, or someone is impersonating the channel.", fix_lead: "", fix_cmd: "",
        fix_note: "Check that the manifest URL is the channel you meant. If it is, update idris2x, because key changes ship in launcher releases. Never swap the trusted key by hand.", auto: "none" },
    CaseDef { error: 3, case: "malformed", summary: "cannot read signature material: {what}", story: "I could not read the signature material: {what}.", facts: &[("file", "file")],
        state: "The manifest was discarded. Your lock file and store are unchanged, and everything already pinned still runs.", why: "The file is not a signify-format Ed25519 key or signature. A proxy or captive portal that returns a web page in place of the file is the usual cause.", fix_lead: "", fix_cmd: "",
        fix_note: "Open the file named above. If it contains HTML, fix the proxy or network first, then run the same command again.", auto: "none" },
    CaseDef { error: 11, case: "capsule-missing", summary: "a pinned capsule is not in the store and {mode} is set", story: "I need a capsule that is not in the store, and offline mode is on.", facts: &[("capsule", "digest"), ("store", "store"), ("offline-because", "mode")],
        state: "Nothing was downloaded, as you asked. The store is unchanged.", why: "Offline mode never touches the network, so the capsule has to arrive another way.", fix_lead: "", fix_cmd: "idris2x fetch -o capsule.tar.gz",
        fix_note: "Run that on a connected machine with the same {lock}, copy capsule.tar.gz here, then run: idris2x install --from capsule.tar.gz", auto: "none" },
    CaseDef { error: 11, case: "no-manifest", summary: "no cached channel manifest and {mode} is set", story: "Pinning needs the channel manifest. None is cached, and offline mode is on.", facts: &[("cache", "cache"), ("offline-because", "mode")],
        state: "Nothing was changed.", why: "pin reads the signed channel manifest. Offline, it can only use a copy cached by an earlier online pin.", fix_lead: "Run the pin once with the network allowed:", fix_cmd: "IDRIS2X_OFFLINE=0 idris2x pin {version}",
        fix_note: "Running an already pinned toolchain never needs the manifest: install --locked and exec --locked work offline from the store.", auto: "none" },
    CaseDef { error: 6, case: "held", summary: "waited {seconds}s for another install of the same capsule", story: "Another idris2x is installing the same capsule. I waited {seconds} seconds and then gave up.", facts: &[("capsule", "digest"), ("lock-file", "lockfile"), ("held-by", "holder")],
        state: "This run installed nothing. The other install is not affected.", why: "Installs of one capsule take turns, so two processes never write the same store entry. A slow download in the other process is the usual cause.", fix_lead: "Wait for the other install to finish, or allow more time:", fix_cmd: "IDRIS2X_LOCK_TIMEOUT=1800 idris2x install --locked",
        fix_note: "Do not delete the lock file while its holder is running: two installs would then write at once. The lock is released by itself when the holder exits.", auto: "safe" },
    CaseDef { error: 0, case: "unknown-command", summary: "no such command: {word}", story: "I do not know the command {word}.", facts: &[("you-typed", "word"), ("commands", "commands")],
        state: "Nothing was run.", why: "The first word after idris2x must be one of the commands listed above.", fix_lead: "See what each command does:", fix_cmd: "idris2x help",
        fix_note: "", auto: "none" },
    CaseDef { error: 0, case: "unknown-flag", summary: "{command} does not take {word}", story: "The {command} command does not take {word}.", facts: &[("you-typed", "word"), ("usage", "usage")],
        state: "Nothing was run.", why: "Each command accepts only the flags shown in its usage line.", fix_lead: "", fix_cmd: "",
        fix_note: "Run the command again in the form shown after usage.", auto: "none" },
    CaseDef { error: 0, case: "missing-argument", summary: "{command} needs {what}", story: "The {command} command needs {what}.", facts: &[("usage", "usage")],
        state: "Nothing was run.", why: "The command cannot choose this value for you.", fix_lead: "", fix_cmd: "",
        fix_note: "Run the command again in the form shown after usage.", auto: "none" },
    CaseDef { error: 0, case: "no-such-file", summary: "no such file: {path}", story: "I cannot find the file {path}.", facts: &[("you-gave", "path"), ("looked-from", "dir")],
        state: "Nothing was installed or changed.", why: "A relative path is read from the current directory.", fix_lead: "", fix_cmd: "",
        fix_note: "Check the spelling, or give the full path.", auto: "none" },
    CaseDef { error: 0, case: "no-such-id", summary: "no such error id: {word}", story: "There is no error called {word}.", facts: &[("you-typed", "word")],
        state: "Nothing was run.", why: "Error ids are written in capitals and start with E-, exactly as a message prints them.", fix_lead: "List every id:", fix_cmd: "idris2x explain",
        fix_note: "", auto: "safe" },
    CaseDef { error: 0, case: "prototype-setting", summary: "{variable} is not set", story: "The prototype needs {variable} to be set.", facts: &[("missing", "variable"), ("holds", "what")],
        state: "Nothing was run.", why: "The bash prototype reads its channel address and trusted key from the environment. The real launcher will have both built in.", fix_lead: "", fix_cmd: "",
        fix_note: "Set {variable} and run the command again. See scripts/proto/chaos.sh for a working example.", auto: "none" },
    CaseDef { error: 0, case: "bad-setting", summary: "{variable} is not {what}", story: "{variable} must be {what}, and it is set to something else.", facts: &[("setting", "variable"), ("value", "value")],
        state: "Nothing was run.", why: "idris2x refuses a setting it cannot read. It does not fall back to a default, so a typo never changes what runs.", fix_lead: "", fix_cmd: "",
        fix_note: "Set {variable} to {what}, or unset it to use the default.", auto: "none" },
    CaseDef { error: 4, case: "unknown-arch", summary: "no capsules are built for the {arch} processor type", story: "No capsules are built for this machine's processor type, {arch}.", facts: &[("this-machine", "arch"), ("supported", "supported")],
        state: "Nothing was downloaded or changed.", why: "Each capsule holds programs compiled for one processor type and operating system, and none has been built for this pair.", fix_lead: "", fix_cmd: "",
        fix_note: "See the supported platforms page for the list and for how to ask for a new target. Building Idris 2 from source remains possible without idris2x.", auto: "none" },
    CaseDef { error: 4, case: "unknown-os", summary: "no capsules are built for the {os} operating system", story: "No capsules are built for this operating system, {os}.", facts: &[("this-machine", "os"), ("supported", "supported")],
        state: "Nothing was downloaded or changed.", why: "Each capsule holds programs compiled for one processor type and operating system, and none has been built for this pair.", fix_lead: "", fix_cmd: "",
        fix_note: "See the supported platforms page for the list and for how to ask for a new target. Building Idris 2 from source remains possible without idris2x.", auto: "none" },
    CaseDef { error: 5, case: "all-mirrors-failed", summary: "every mirror failed for the pinned capsule", story: "I could not download the pinned capsule from any mirror.", facts: &[("capsule", "digest"), ("tried", "tried"), ("full-log", "log")],
        state: "Nothing was installed. The store is unchanged.", why: "Each address in the lock was tried in turn and each one failed for the reason shown after it.", fix_lead: "When the network is back, run it again:", fix_cmd: "idris2x install --locked",
        fix_note: "If you are behind a proxy, check that HTTPS_PROXY is set. If every mirror answers 404, the capsule was withdrawn: see the runbook below.", auto: "safe" },
    CaseDef { error: 5, case: "manifest-unreachable", summary: "cannot fetch the channel manifest", story: "I could not fetch the channel manifest.", facts: &[("manifest", "url"), ("tried", "tried"), ("full-log", "log")],
        state: "The lock file was not changed. Everything already pinned still runs.", why: "pin needs a fresh copy of the signed manifest, and the address above did not provide one.", fix_lead: "When the network is back, run it again:", fix_cmd: "idris2x pin {version}",
        fix_note: "Running an already pinned toolchain does not need the network once its capsule is installed.", auto: "safe" },
    CaseDef { error: 7, case: "too-old", summary: "this system has glibc {host}, older than the pinned capsule needs", story: "This system's C library is too old for the pinned capsule.", facts: &[("this-system", "host"), ("capsule-needs", "needs"), ("capsule", "digest")],
        state: "Nothing was downloaded or changed.", why: "The capsule's programs were built against a newer glibc. On an older glibc they would fail to start, with a less clear message than this one.", fix_lead: "", fix_cmd: "",
        fix_note: "Run this project in a newer distribution or container image, one with at least the glibc shown above. This check cannot be skipped.", auto: "none" },
    CaseDef { error: 7, case: "unknown", summary: "cannot tell which glibc this system has", story: "The pinned capsule needs a minimum glibc, and I could not find out which glibc this system has.", facts: &[("capsule-needs", "needs"), ("capsule", "digest")],
        state: "Nothing was downloaded or changed.", why: "idris2x asks getconf GNU_LIBC_VERSION, with only PATH passed on from the environment. Either getconf is not on PATH, or this system's C library is not glibc: musl, as on Alpine, is not supported. A capsule on a C library it was not built for fails to start, with a less clear message than this one.", fix_lead: "", fix_cmd: "",
        fix_note: "Put getconf on PATH (on Debian and Ubuntu it is in the libc-bin package), or run this project in a glibc-based distribution or container image. This check cannot be skipped.", auto: "none" },
    CaseDef { error: 8, case: "chez-failed", summary: "Chez Scheme from the capsule does not run here", story: "The capsule's Chez Scheme did not run correctly on this machine.", facts: &[("check", "probe"), ("chez-said", "output")],
        state: "The capsule was not installed. The store is unchanged.", why: "The capsule's files are intact, since the checksums passed, so something about this machine stops the program running: a missing system library, a security policy, or an unsupported processor.", fix_lead: "Collect the facts for a report:", fix_cmd: "idris2x doctor",
        fix_note: "The line after chez-said is Chez Scheme's own message, not ours. Send it with the doctor output using the runbook below.", auto: "safe" },
    CaseDef { error: 8, case: "idris2-failed", summary: "Idris 2 from the capsule does not start here", story: "The capsule's Idris 2 did not start on this machine.", facts: &[("check", "probe"), ("idris2-said", "output")],
        state: "The capsule was not installed. The store is unchanged.", why: "Chez Scheme runs, so the fault is in starting the compiler itself: usually its support library could not be loaded.", fix_lead: "Collect the facts for a report:", fix_cmd: "idris2x doctor",
        fix_note: "The line after idris2-said is Idris 2's own message, not ours. Report this to idris2x, not to the Idris 2 project: the fault is in how the capsule was built or run.", auto: "safe" },
    CaseDef { error: 8, case: "version-mismatch", summary: "the compiler in the capsule reports a different version than the capsule says it holds", story: "The capsule says it holds one version of Idris 2, and the compiler inside reports another.", facts: &[("capsule-says", "want"), ("compiler-reports", "got")],
        state: "The capsule was not installed. The store is unchanged.", why: "The capsule was labelled wrongly when it was built. This is a fault in the capsule, not in your machine.", fix_lead: "", fix_cmd: "",
        fix_note: "Report the capsule using the runbook below. Until it is replaced, pin a different version.", auto: "none" },
    CaseDef { error: 8, case: "path-has-spaces", summary: "compiled programs cannot start because the store path contains a space", story: "Programs compiled by this toolchain cannot start, because the store path contains a space.", facts: &[("check", "probe"), ("store-entry", "store")],
        state: "The capsule is installed and the compiler itself works. Only programs it compiles with the Chez backend are affected.", why: "A compiled program begins with a line naming Chez Scheme by its full path, and the operating system splits that line at spaces.", fix_lead: "Move the store to a path without spaces, then install again:", fix_cmd: "export IDRIS2X_CACHE=\"$HOME/.cache/idris2x\"",
        fix_note: "Any directory whose full path has no spaces will do. Programs built with --cg refc are not affected.", auto: "none" },
    CaseDef { error: 8, case: "codegen-failed", summary: "a test program did not compile and run: {probe}", story: "A small test program did not compile and run with this toolchain.", facts: &[("check", "probe"), ("store-entry", "store")],
        state: "The capsule is installed. Nothing else was changed.", why: "The compiler starts, and building or running a program with it fails on this machine.", fix_lead: "Collect the facts for a report:", fix_cmd: "idris2x doctor",
        fix_note: "Send the doctor output using the runbook below.", auto: "safe" },
    CaseDef { error: 9, case: "lock-newer", summary: "{file} uses a newer lock format; this idris2x reads up to {supports}", story: "{file} was written by a newer idris2x than this one.", facts: &[("file", "file"), ("its-format", "found"), ("this-idris2x-reads", "supports"), ("this-idris2x", "version")],
        state: "Nothing was downloaded or changed. The lock file is intact.", why: "Someone pinned this project with a newer idris2x. An older one refuses to guess at fields it does not know.", fix_lead: "", fix_cmd: "",
        fix_note: "Update idris2x to the version your colleagues use, then run the same command again.", auto: "none" },
    CaseDef { error: 9, case: "channel-newer", summary: "the channel uses a newer manifest format; this idris2x reads up to {supports}", story: "The channel now publishes a newer manifest format than this idris2x reads.", facts: &[("manifest", "url"), ("its-format", "found"), ("this-idris2x-reads", "supports"), ("this-idris2x", "version")],
        state: "The lock file was not changed. Everything already pinned still runs.", why: "The channel moved to a new format after this idris2x was released.", fix_lead: "", fix_cmd: "",
        fix_note: "Update idris2x, then pin again. Until then, existing pins keep working.", auto: "none" },
    CaseDef { error: 10, case: "toml-vs-lock", summary: "idris2x.toml asks for a different idris2 version than idris2x.lock pins", story: "idris2x.toml and idris2x.lock name different versions of Idris 2.", facts: &[("idris2x.toml", "toml"), ("idris2x.lock", "locked")],
        state: "Nothing was downloaded or changed.", why: "One of the two files was edited without the other. With --locked the lock is never rewritten to match.", fix_lead: "Make the lock match idris2x.toml:", fix_cmd: "idris2x pin {toml}",
        fix_note: "If the lock is the one that is right, change the version in idris2x.toml to the one idris2x.lock pins instead.", auto: "none" },
    CaseDef { error: 12, case: "unsafe-path", summary: "the capsule archive has a member that would be written outside the store", story: "The capsule archive contains a file that would be written outside the store, so I refused to unpack it.", facts: &[("capsule", "digest")],
        state: "Nothing was unpacked or installed. The archive was deleted.", why: "The archive has an absolute path, a .. component or a link that leaves its own directory. A correctly built capsule never does, so the archive is faulty or hostile.", fix_lead: "", fix_cmd: "",
        fix_note: "Do not unpack it by hand. Report the digest above to idris2x using the runbook below.", auto: "none" },
    CaseDef { error: 12, case: "no-metadata", summary: "the capsule archive has no capsule.json", story: "The capsule archive has no capsule.json, so I cannot tell what it holds.", facts: &[("capsule", "digest")],
        state: "Nothing was installed. The unpacked files were deleted.", why: "Every capsule describes itself in capsule.json. This archive matched its digest and is not a capsule, which is a fault in how it was built.", fix_lead: "", fix_cmd: "",
        fix_note: "Report the digest above to idris2x using the runbook below.", auto: "none" },
    CaseDef { error: 12, case: "tree-mismatch", summary: "the capsule's files do not match its own checksum list", story: "The capsule unpacked, and its files do not match its own checksum list.", facts: &[("capsule", "digest")],
        state: "Nothing was installed. The unpacked files were deleted.", why: "The archive as a whole matched the lock, so the fault was built into the capsule, or the disk damaged the files while unpacking.", fix_lead: "Try once more, in case the disk was at fault:", fix_cmd: "idris2x install --locked",
        fix_note: "If it fails the same way, report the digest above to idris2x using the runbook below.", auto: "safe" },
    CaseDef { error: 12, case: "bad-metadata", summary: "the capsule's capsule.json does not describe it", story: "The capsule has a capsule.json, and it does not say what the capsule holds.", facts: &[("capsule", "digest")],
        state: "Nothing was installed. The unpacked files were deleted.", why: "capsule.json must be a JSON object that names the capsule, gives its Chez Scheme version and, if the capsule has Idris 2, its version too. This archive matched its digest, so the fault was built into the capsule.", fix_lead: "", fix_cmd: "",
        fix_note: "Report the digest above to idris2x using the runbook below.", auto: "none" },
    CaseDef { error: 13, case: "version-went-back", summary: "the channel offered an older manifest version than this project has already seen", story: "The channel offered an older manifest than this project has already seen.", facts: &[("manifest", "url"), ("lock-has-seen", "seen"), ("now-offered", "offered")],
        state: "The lock file was not changed. Everything already pinned still runs.", why: "Manifest versions only go up. An older one usually means a mirror that has not caught up. It can also be an attempt to hide a newer release.", fix_lead: "Wait an hour, then try again:", fix_cmd: "idris2x pin {version}",
        fix_note: "If it is still older tomorrow, report it using the runbook below. There is no flag that accepts an older manifest.", auto: "none" },
    CaseDef { error: 14, case: "expired", summary: "the channel manifest has expired", story: "The channel manifest is past its expiry time.", facts: &[("manifest", "url"), ("expired-at", "expires"), ("this-clock-says", "now")],
        state: "The lock file was not changed. Everything already pinned still runs.", why: "Manifests are re-signed regularly, so a stale one means a mirror is serving an old copy, the channel is no longer maintained, or this machine's clock is wrong.", fix_lead: "Check the clock line above. If it is right, try again later:", fix_cmd: "idris2x pin {version}",
        fix_note: "To pin from the expired manifest anyway, set IDRIS2X_ALLOW_EXPIRED=1. That gives up protection against being shown an outdated list of releases, so use it only when you know why the manifest is old.", auto: "none" },
    CaseDef { error: 15, case: "cannot-create", summary: "cannot create {path}", story: "I could not create a directory the store needs.", facts: &[("path", "path")],
        state: "Nothing was installed.", why: "The directory's parent is missing, read-only, or owned by another user.", fix_lead: "Either fix the permissions, or put the store somewhere you can write:", fix_cmd: "export IDRIS2X_CACHE=\"$HOME/.cache/idris2x\"",
        fix_note: "The store path must not contain spaces if you compile programs with the Chez backend.", auto: "none" },
    CaseDef { error: 15, case: "write-failed", summary: "writing to the store failed: {detail}", story: "I could not finish writing to the store.", facts: &[("while", "detail"), ("store", "path")],
        state: "Nothing was installed. Partly written files were removed, and existing capsules are untouched.", why: "The disk is full, a quota or file-size limit was reached, or the store became read-only.", fix_lead: "Free some space, for example by removing capsules you no longer use:", fix_cmd: "idris2x gc",
        fix_note: "Then run the same command again.", auto: "none" },
    CaseDef { error: 15, case: "rename-failed", summary: "cannot move the unpacked capsule into place", story: "The capsule unpacked correctly, and I could not move it into its place in the store.", facts: &[("store-entry", "path")],
        state: "Nothing was installed. The unpacked files were removed.", why: "The final step is a single rename, so that a capsule is either complete or absent. The rename fails when the store and its staging area are on different filesystems, or the store is read-only.", fix_lead: "", fix_cmd: "",
        fix_note: "Check that the store directory is on one writable filesystem, then run the same command again.", auto: "none" },
    CaseDef { error: 15, case: "no-cache-dir", summary: "cannot tell where the store should be", story: "IDRIS2X_CACHE, XDG_CACHE_HOME and HOME are all unset, so I cannot tell where the store should be.", facts: &[],
        state: "Nothing was downloaded or changed.", why: "idris2x keeps capsules in IDRIS2X_CACHE, else in XDG_CACHE_HOME/idris2x, else in HOME/.cache/idris2x. It does not fall back to the current directory, which would put a separate store in each project.", fix_lead: "Choose a directory for the store, then run the same command again:", fix_cmd: "export IDRIS2X_CACHE=<directory>",
        fix_note: "The store path must not contain spaces if you compile programs with the Chez backend.", auto: "placeholder" },
    CaseDef { error: 16, case: "write-failed", summary: "cannot write the output: {detail}", story: "I could not write my output, so it is incomplete.", facts: &[("reason", "detail")],
        state: "The output is incomplete. Anything the command did before it tried to write is kept.", why: "The disk or file that the output goes to is full, or the program reading it stopped before the end, as head does.", fix_lead: "", fix_cmd: "",
        fix_note: "Send the output to a file on a disk with free space, or to a program that reads all of it, then run the same command again.", auto: "none" },
    CaseDef { error: 17, case: "bug", summary: "internal error: {detail}", story: "I have hit a bug in idris2x itself.", facts: &[("what", "detail"), ("idris2x-version", "version")],
        state: "Unknown. Run idris2x verify to check the installed capsule.", why: "This is a fault in idris2x, not something you did.", fix_lead: "Collect the facts, then open an issue with them:", fix_cmd: "idris2x doctor",
        fix_note: "Attach the doctor output and the command you ran to a new issue at https://github.com/metadatastician/idris2x/issues", auto: "safe" },
    CaseDef { error: 17, case: "missing-tool", summary: "the prototype needs {tool} and cannot find it", story: "The bash prototype needs the program {tool}, and it is not installed.", facts: &[("missing", "tool")],
        state: "Nothing was run.", why: "The prototype is a shell script that calls ordinary system tools. The real launcher will not need them.", fix_lead: "", fix_cmd: "",
        fix_note: "Install {tool} with your system's package manager, then run the same command again.", auto: "none" },
];

pub(crate) static ADVICE: [AdviceDef; 2] = [
    AdviceDef { text: "{names} is set in your shell and idris2x will ignore it. Pass --inherit-env to keep it.", facts: &[], silence: "IDRIS2X_ADVICE_ENV" },
    AdviceDef { text: "idris2-lsp on PATH does not report the Idris 2 version this project pins. Editors may show wrong errors until it is rebuilt for that version.", facts: &[("project-pins", "pinned")], silence: "IDRIS2X_ADVICE_LSP" },
];

/// Every way the launcher can fail: one variant per `[[case]]` in errors.toml.
pub enum Fail {
    /// E-PIN-NOT-FOUND, case `no-lock`.
    PinNotFoundNoLock { dir: Prose, lock: Prose },
    /// E-PIN-NOT-FOUND, case `no-target`.
    PinNotFoundNoTarget { target: Prose, covered: Fact, lock: Prose, version: Fix },
    /// E-PIN-NOT-FOUND, case `no-version`.
    PinNotFoundNoVersion { version: Prose, available: Fact, lock: Prose },
    /// E-PIN-NOT-FOUND, case `not-installed`.
    PinNotFoundNotInstalled { digest: Fact },
    /// E-PIN-NOT-FOUND, case `no-idris2`.
    PinNotFoundNoIdris2 { name: Fact },
    /// E-PIN-NOT-FOUND, case `no-urls`.
    PinNotFoundNoUrls { digest: Fact, lock: Prose, version: Fix },
    /// E-PIN-NOT-FOUND, case `malformed-lock`.
    PinNotFoundMalformedLock { target: Fact, field: Prose, lock: Prose },
    /// E-PIN-NOT-FOUND, case `unreadable-lock`.
    PinNotFoundUnreadableLock { problem: Fact, lock: Prose },
    /// E-HASH-MISMATCH, case `download`.
    HashMismatchDownload { want: Fact, got: Fact, bytes: Fact, source: Fact, lock: Prose },
    /// E-HASH-MISMATCH, case `bundle`.
    HashMismatchBundle { want: Fact, got: Fact, bytes: Fact, source: Prose, lock: Prose },
    /// E-HASH-MISMATCH, case `store-modified`.
    HashMismatchStoreModified { digest: Fact, dir: Fix },
    /// E-SIG-INVALID, case `bad-signature`.
    SigInvalidBadSignature { url: Fact, key: Fact, version: Fix },
    /// E-SIG-INVALID, case `wrong-key`.
    SigInvalidWrongKey { url: Fact, signer: Fact, key: Fact },
    /// E-SIG-INVALID, case `malformed`.
    SigInvalidMalformed { file: Fact, what: Prose },
    /// E-OFFLINE, case `capsule-missing`.
    OfflineCapsuleMissing { digest: Fact, store: Fact, mode: Prose, lock: Prose },
    /// E-OFFLINE, case `no-manifest`.
    OfflineNoManifest { cache: Fact, mode: Prose, version: Fix },
    /// E-LOCK-TIMEOUT, case `held`.
    LockTimeoutHeld { digest: Fact, lockfile: Fact, holder: Fact, seconds: Prose },
    /// E-USAGE, case `unknown-command`.
    UsageUnknownCommand { word: Prose, commands: Fact },
    /// E-USAGE, case `unknown-flag`.
    UsageUnknownFlag { word: Prose, usage: Fact, command: Prose },
    /// E-USAGE, case `missing-argument`.
    UsageMissingArgument { usage: Fact, command: Prose, what: Prose },
    /// E-USAGE, case `no-such-file`.
    UsageNoSuchFile { path: Prose, dir: Fact },
    /// E-USAGE, case `no-such-id`.
    UsageNoSuchId { word: Prose },
    /// E-USAGE, case `prototype-setting`.
    UsagePrototypeSetting { variable: Prose, what: Fact },
    /// E-USAGE, case `bad-setting`.
    UsageBadSetting { variable: Prose, value: Fact, what: Prose },
    /// E-PLATFORM-UNSUPPORTED, case `unknown-arch`.
    PlatformUnsupportedUnknownArch { arch: Prose, supported: Fact },
    /// E-PLATFORM-UNSUPPORTED, case `unknown-os`.
    PlatformUnsupportedUnknownOs { os: Prose, supported: Fact },
    /// E-NETWORK, case `all-mirrors-failed`.
    NetworkAllMirrorsFailed { digest: Fact, tried: Fact, log: Fact },
    /// E-NETWORK, case `manifest-unreachable`.
    NetworkManifestUnreachable { url: Fact, tried: Fact, log: Fact, version: Fix },
    /// E-GLIBC-FLOOR, case `too-old`.
    GlibcFloorTooOld { host: Prose, needs: Fact, digest: Fact },
    /// E-GLIBC-FLOOR, case `unknown`.
    GlibcFloorUnknown { needs: Fact, digest: Fact },
    /// E-PROBE-CODEGEN, case `chez-failed`.
    ProbeCodegenChezFailed { probe: Fact, output: Fact },
    /// E-PROBE-CODEGEN, case `idris2-failed`.
    ProbeCodegenIdris2Failed { probe: Fact, output: Fact },
    /// E-PROBE-CODEGEN, case `version-mismatch`.
    ProbeCodegenVersionMismatch { want: Fact, got: Fact },
    /// E-PROBE-CODEGEN, case `path-has-spaces`.
    ProbeCodegenPathHasSpaces { probe: Fact, store: Fact },
    /// E-PROBE-CODEGEN, case `codegen-failed`.
    ProbeCodegenCodegenFailed { probe: Prose, store: Fact },
    /// E-CHANNEL-SCHEMA, case `lock-newer`.
    ChannelSchemaLockNewer { file: Prose, found: Fact, supports: Prose, version: Fact },
    /// E-CHANNEL-SCHEMA, case `channel-newer`.
    ChannelSchemaChannelNewer { url: Fact, found: Fact, supports: Prose, version: Fact },
    /// E-PIN-DRIFT, case `toml-vs-lock`.
    PinDriftTomlVsLock { toml: Fix, locked: Fact },
    /// E-CAPSULE-INVALID, case `unsafe-path`.
    CapsuleInvalidUnsafePath { digest: Fact },
    /// E-CAPSULE-INVALID, case `no-metadata`.
    CapsuleInvalidNoMetadata { digest: Fact },
    /// E-CAPSULE-INVALID, case `tree-mismatch`.
    CapsuleInvalidTreeMismatch { digest: Fact },
    /// E-CAPSULE-INVALID, case `bad-metadata`.
    CapsuleInvalidBadMetadata { digest: Fact },
    /// E-CHANNEL-ROLLBACK, case `version-went-back`.
    ChannelRollbackVersionWentBack { url: Fact, seen: Fact, offered: Fact, version: Fix },
    /// E-CHANNEL-EXPIRED, case `expired`.
    ChannelExpiredExpired { url: Fact, expires: Fact, now: Fact, version: Fix },
    /// E-STORE-IO, case `cannot-create`.
    StoreIoCannotCreate { path: Prose },
    /// E-STORE-IO, case `write-failed`.
    StoreIoWriteFailed { detail: Prose, path: Fact },
    /// E-STORE-IO, case `rename-failed`.
    StoreIoRenameFailed { path: Fact },
    /// E-STORE-IO, case `no-cache-dir`.
    StoreIoNoCacheDir {  },
    /// E-OUTPUT, case `write-failed`.
    OutputWriteFailed { detail: Prose },
    /// E-INTERNAL, case `bug`.
    InternalBug { detail: Prose, version: Fact },
    /// E-INTERNAL, case `missing-tool`.
    InternalMissingTool { tool: Prose },
}

/// Every note that is not an error: one variant per `[[advice]]`. A key in its text is prose, one only on a fact line is a fact.
pub enum Advice {
    EnvIgnored { names: Prose },
    LspMismatch { pinned: Fact },
}

impl Fail {
    /// The index of this case in `CASES`, and its context values in field order.
    fn parts(&self) -> (usize, Vec<(&'static str, &str)>) {
        match self {
            Fail::PinNotFoundNoLock { dir, lock } => (0, vec![("dir", &*dir.0), ("lock", &*lock.0)]),
            Fail::PinNotFoundNoTarget { target, covered, lock, version } => (1, vec![("target", &*target.0), ("covered", &*covered.0), ("lock", &*lock.0), ("version", &*version.0)]),
            Fail::PinNotFoundNoVersion { version, available, lock } => (2, vec![("version", &*version.0), ("available", &*available.0), ("lock", &*lock.0)]),
            Fail::PinNotFoundNotInstalled { digest } => (3, vec![("digest", &*digest.0)]),
            Fail::PinNotFoundNoIdris2 { name } => (4, vec![("name", &*name.0)]),
            Fail::PinNotFoundNoUrls { digest, lock, version } => (5, vec![("digest", &*digest.0), ("lock", &*lock.0), ("version", &*version.0)]),
            Fail::PinNotFoundMalformedLock { target, field, lock } => (6, vec![("target", &*target.0), ("field", &*field.0), ("lock", &*lock.0)]),
            Fail::PinNotFoundUnreadableLock { problem, lock } => (7, vec![("problem", &*problem.0), ("lock", &*lock.0)]),
            Fail::HashMismatchDownload { want, got, bytes, source, lock } => (8, vec![("want", &*want.0), ("got", &*got.0), ("bytes", &*bytes.0), ("source", &*source.0), ("lock", &*lock.0)]),
            Fail::HashMismatchBundle { want, got, bytes, source, lock } => (9, vec![("want", &*want.0), ("got", &*got.0), ("bytes", &*bytes.0), ("source", &*source.0), ("lock", &*lock.0)]),
            Fail::HashMismatchStoreModified { digest, dir } => (10, vec![("digest", &*digest.0), ("dir", &*dir.0)]),
            Fail::SigInvalidBadSignature { url, key, version } => (11, vec![("url", &*url.0), ("key", &*key.0), ("version", &*version.0)]),
            Fail::SigInvalidWrongKey { url, signer, key } => (12, vec![("url", &*url.0), ("signer", &*signer.0), ("key", &*key.0)]),
            Fail::SigInvalidMalformed { file, what } => (13, vec![("file", &*file.0), ("what", &*what.0)]),
            Fail::OfflineCapsuleMissing { digest, store, mode, lock } => (14, vec![("digest", &*digest.0), ("store", &*store.0), ("mode", &*mode.0), ("lock", &*lock.0)]),
            Fail::OfflineNoManifest { cache, mode, version } => (15, vec![("cache", &*cache.0), ("mode", &*mode.0), ("version", &*version.0)]),
            Fail::LockTimeoutHeld { digest, lockfile, holder, seconds } => (16, vec![("digest", &*digest.0), ("lockfile", &*lockfile.0), ("holder", &*holder.0), ("seconds", &*seconds.0)]),
            Fail::UsageUnknownCommand { word, commands } => (17, vec![("word", &*word.0), ("commands", &*commands.0)]),
            Fail::UsageUnknownFlag { word, usage, command } => (18, vec![("word", &*word.0), ("usage", &*usage.0), ("command", &*command.0)]),
            Fail::UsageMissingArgument { usage, command, what } => (19, vec![("usage", &*usage.0), ("command", &*command.0), ("what", &*what.0)]),
            Fail::UsageNoSuchFile { path, dir } => (20, vec![("path", &*path.0), ("dir", &*dir.0)]),
            Fail::UsageNoSuchId { word } => (21, vec![("word", &*word.0)]),
            Fail::UsagePrototypeSetting { variable, what } => (22, vec![("variable", &*variable.0), ("what", &*what.0)]),
            Fail::UsageBadSetting { variable, value, what } => (23, vec![("variable", &*variable.0), ("value", &*value.0), ("what", &*what.0)]),
            Fail::PlatformUnsupportedUnknownArch { arch, supported } => (24, vec![("arch", &*arch.0), ("supported", &*supported.0)]),
            Fail::PlatformUnsupportedUnknownOs { os, supported } => (25, vec![("os", &*os.0), ("supported", &*supported.0)]),
            Fail::NetworkAllMirrorsFailed { digest, tried, log } => (26, vec![("digest", &*digest.0), ("tried", &*tried.0), ("log", &*log.0)]),
            Fail::NetworkManifestUnreachable { url, tried, log, version } => (27, vec![("url", &*url.0), ("tried", &*tried.0), ("log", &*log.0), ("version", &*version.0)]),
            Fail::GlibcFloorTooOld { host, needs, digest } => (28, vec![("host", &*host.0), ("needs", &*needs.0), ("digest", &*digest.0)]),
            Fail::GlibcFloorUnknown { needs, digest } => (29, vec![("needs", &*needs.0), ("digest", &*digest.0)]),
            Fail::ProbeCodegenChezFailed { probe, output } => (30, vec![("probe", &*probe.0), ("output", &*output.0)]),
            Fail::ProbeCodegenIdris2Failed { probe, output } => (31, vec![("probe", &*probe.0), ("output", &*output.0)]),
            Fail::ProbeCodegenVersionMismatch { want, got } => (32, vec![("want", &*want.0), ("got", &*got.0)]),
            Fail::ProbeCodegenPathHasSpaces { probe, store } => (33, vec![("probe", &*probe.0), ("store", &*store.0)]),
            Fail::ProbeCodegenCodegenFailed { probe, store } => (34, vec![("probe", &*probe.0), ("store", &*store.0)]),
            Fail::ChannelSchemaLockNewer { file, found, supports, version } => (35, vec![("file", &*file.0), ("found", &*found.0), ("supports", &*supports.0), ("version", &*version.0)]),
            Fail::ChannelSchemaChannelNewer { url, found, supports, version } => (36, vec![("url", &*url.0), ("found", &*found.0), ("supports", &*supports.0), ("version", &*version.0)]),
            Fail::PinDriftTomlVsLock { toml, locked } => (37, vec![("toml", &*toml.0), ("locked", &*locked.0)]),
            Fail::CapsuleInvalidUnsafePath { digest } => (38, vec![("digest", &*digest.0)]),
            Fail::CapsuleInvalidNoMetadata { digest } => (39, vec![("digest", &*digest.0)]),
            Fail::CapsuleInvalidTreeMismatch { digest } => (40, vec![("digest", &*digest.0)]),
            Fail::CapsuleInvalidBadMetadata { digest } => (41, vec![("digest", &*digest.0)]),
            Fail::ChannelRollbackVersionWentBack { url, seen, offered, version } => (42, vec![("url", &*url.0), ("seen", &*seen.0), ("offered", &*offered.0), ("version", &*version.0)]),
            Fail::ChannelExpiredExpired { url, expires, now, version } => (43, vec![("url", &*url.0), ("expires", &*expires.0), ("now", &*now.0), ("version", &*version.0)]),
            Fail::StoreIoCannotCreate { path } => (44, vec![("path", &*path.0)]),
            Fail::StoreIoWriteFailed { detail, path } => (45, vec![("detail", &*detail.0), ("path", &*path.0)]),
            Fail::StoreIoRenameFailed { path } => (46, vec![("path", &*path.0)]),
            Fail::StoreIoNoCacheDir {  } => (47, vec![]),
            Fail::OutputWriteFailed { detail } => (48, vec![("detail", &*detail.0)]),
            Fail::InternalBug { detail, version } => (49, vec![("detail", &*detail.0), ("version", &*version.0)]),
            Fail::InternalMissingTool { tool } => (50, vec![("tool", &*tool.0)]),
        }
    }
}

impl Advice {
    /// The index of this note in `ADVICE`, and its context values.
    fn parts(&self) -> (usize, Vec<(&'static str, &str)>) {
        match self {
            Advice::EnvIgnored { names } => (0, vec![("names", &*names.0)]),
            Advice::LspMismatch { pinned } => (1, vec![("pinned", &*pinned.0)]),
        }
    }
}
